R=Path(__file__).resolve().parents[2];name='quarter_'+secrets.token_hex(4);base=['docker','--host=unix:///var/run/docker.sock','exec','-i','paperlab-research-sql','psql','-U','postgres','-v','ON_ERROR_STOP=1','-At']
def q(s,db=name,error=None):
 p=subprocess.run(base+['-d',db],input=s.encode(),capture_output=True)
 if error:assert p.returncode and error in p.stderr.decode(),p.stderr.decode()
 else:assert not p.returncode,p.stderr.decode()
 return p.stdout.decode().strip().splitlines()[-1]if p.stdout.strip()else''
